PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS 'Olympia' (
  'jahr' int(11) NOT NULL,
  'sportart' varchar(100) NOT NULL,
  'disziplin' varchar(100) NOT NULL,
  'nachname' varchar(100) NOT NULL,
  'vorname' varchar(100) NOT NULL,
  'geschlecht' char(1) DEFAULT NULL,
  'platzierung' varchar(6) DEFAULT NULL,
  'herkunftsland' varchar(100) NOT NULL,
  'austragungsort' varchar(100) NOT NULL,
  PRIMARY KEY ('jahr','sportart','disziplin','nachname','vorname')
);
COMMIT;
